export type DrugDosing = {
  mgPerKg: number;
  freq: string;
  duration: string;
  note?: string;
};

/** Запись без текстов инструкции (источник истины справочника дозировок). */
export type DrugCore = {
  id: string;
  nameRu: string;
  category: string;
  summary: string;
  dosing: Partial<Record<AnimalKey, DrugDosing>>;
  warnings?: string;
};

/** Полная запись для калькулятора и справочника. */
export interface DrugRecord extends DrugCore {
  /** Обобщённые аптечные памятки (хранение, дача животному); сверять с ИМП конкретной серии/бренда. */
  instruction: string;
}

