export const DRUG_REFERENCE: DrugRecord[] = DRUG_CORE.map((d) => ({
  ...d,
  instruction:
    DRUG_PACKAGE_INSTRUCTION_RU[d.id] ??
    "Применять строго по назначению ветеринарного специалиста по инструкции к конкретной упакованной серии препарата. Храните при температуре указанной на этикетке, в недоступном для детей месте.",
}));

/** Уникальные категории в порядке появления */
export function dosageCategories(ref: DrugRecord[] = DRUG_REFERENCE): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const d of ref) {
    if (!seen.has(d.category)) {
      seen.add(d.category);
      out.push(d.category);
    }
  }
  return out;
}

export function drugById(id: string): DrugRecord | undefined {
  return DRUG_REFERENCE.find((d) => d.id === id);
}

function parseDosingFromApi(raw: Record<string, unknown>): Partial<Record<AnimalKey, DrugDosing>> {
  const out: Partial<Record<AnimalKey, DrugDosing>> = {};
  for (const key of DOSAGE_ANIMAL_KEYS) {
    const v = raw[key];
    if (!v || typeof v !== "object" || Array.isArray(v)) continue;
    const o = v as Record<string, unknown>;
    const mg = Number(o.mgPerKg);
    if (!Number.isFinite(mg)) continue;
    const line: DrugDosing = {
      mgPerKg: mg,
      freq: String(o.freq ?? ""),
      duration: String(o.duration ?? ""),
    };
    if (o.note != null && String(o.note).trim() !== "") {
      line.note = String(o.note);
    }
    out[key] = line;
  }
  return out;
}

function dosageApiRowToRecord(row: DosageDrugApiRow): DrugRecord {
  const dosingRaw =
    row.dosing && typeof row.dosing === "object" && !Array.isArray(row.dosing)
      ? (row.dosing as Record<string, unknown>)
      : {};
  return {
    id: row.id,
    nameRu: row.nameRu,
    category: row.category,
    summary: row.summary,
    instruction: row.instruction,
    warnings: row.warnings,
    dosing: parseDosingFromApi(dosingRaw),
  };
}

/** Записи из БД по id заменяют встроенные; новые id из API дописываются в конец. */
export function mergeDosageCatalogFromApi(apiRows: DosageDrugApiRow[]): DrugRecord[] {
  const apiMap = new Map(apiRows.map((r) => [r.id, dosageApiRowToRecord(r)]));
  const builtinIds = new Set(DRUG_REFERENCE.map((d) => d.id));
  const out: DrugRecord[] = [];
  for (const d of DRUG_REFERENCE) {
    out.push(apiMap.get(d.id) ?? d);
  }
  for (const r of apiRows) {
    if (!builtinIds.has(r.id)) {
      out.push(dosageApiRowToRecord(r));
    }
  }
  return out;
}

export function drugByIdFrom(catalog: DrugRecord[], id: string): DrugRecord | undefined {
  return catalog.find((d) => d.id === id);
}
